/bin/bash -lc "python - <<'PY'
import glob,re
for f in sorted(glob.glob('*.txt')):
 s=open(f).read(); lines=s.splitlines(); page='?'; hits=[]
 for i,l in enumerate(lines):
  if re.match(r'--- page (\\d+) ---',l): page=re.search(r'\\d+',l).group()
  if re.search(r'governed by|governed and|Governing Law|CHOICE OF LAW|construed and interpreted|construed in accordance',l,re.I):
   hits.append((page,' '.join(lines[i:i+4])))
 print(f, hits)
PY"

